CREATE TABLE [purchase].[Suppliers] ([SupplierId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Suppliers_Id] DEFAULT NEWSEQUENTIALID(), [SupplierCode] NVARCHAR(50) NOT NULL, [SupplierName] NVARCHAR(250) NOT NULL, [SupplierType] NVARCHAR(50) NOT NULL, [GSTIN] NVARCHAR(15) NULL, [PAN] NVARCHAR(10) NULL, [MSMERegistrationNumber] NVARCHAR(50) NULL, [Email] NVARCHAR(256) NULL, [Mobile] NVARCHAR(15) NULL, [Telephone] NVARCHAR(20) NULL, [Website] NVARCHAR(300) NULL, [Currency] CHAR(3) NOT NULL CONSTRAINT [DF_Suppliers_Currency] DEFAULT 'INR', [PaymentTermId] UNIQUEIDENTIFIER NULL, [CreditLimit] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_Suppliers_CreditLimit] DEFAULT 0, [OpeningBalance] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_Suppliers_OpeningBalance] DEFAULT 0, [IsGSTRegistered] BIT NOT NULL CONSTRAINT [DF_Suppliers_IsGSTRegistered] DEFAULT 0, [IsTDSApplicable] BIT NOT NULL CONSTRAINT [DF_Suppliers_IsTDSApplicable] DEFAULT 0, [IsActive] BIT NOT NULL CONSTRAINT [DF_Suppliers_IsActive] DEFAULT 1, [IsDeleted] BIT NOT NULL CONSTRAINT [DF_Suppliers_IsDeleted] DEFAULT 0, [Remarks] NVARCHAR(1000) NULL, [CreatedOn] DATETIMEOFFSET NOT NULL CONSTRAINT [DF_Suppliers_CreatedOn] DEFAULT SYSUTCDATETIME(), [CreatedBy] NVARCHAR(256) NULL, [ModifiedOn] DATETIMEOFFSET NULL, [ModifiedBy] NVARCHAR(256) NULL, [RowVersion] ROWVERSION NOT NULL, CONSTRAINT [PK_Suppliers] PRIMARY KEY ([SupplierId]), CONSTRAINT [FK_Suppliers_PaymentTerms] FOREIGN KEY ([PaymentTermId]) REFERENCES [purchase].[SupplierPaymentTerms]([PaymentTermId]), CONSTRAINT [CK_Suppliers_CreditLimit] CHECK ([CreditLimit] >= 0), CONSTRAINT [CK_Suppliers_GSTIN] CHECK ([GSTIN] IS NULL OR LEN([GSTIN]) = 15), CONSTRAINT [CK_Suppliers_PAN] CHECK ([PAN] IS NULL OR LEN([PAN]) = 10));
GO
CREATE UNIQUE INDEX [UX_Suppliers_Code] ON [purchase].[Suppliers]([SupplierCode]) WHERE [IsDeleted] = 0;
GO
CREATE UNIQUE INDEX [UX_Suppliers_GSTIN] ON [purchase].[Suppliers]([GSTIN]) WHERE [GSTIN] IS NOT NULL AND [IsDeleted] = 0;
GO
CREATE INDEX [IX_Suppliers_Search] ON [purchase].[Suppliers]([SupplierName],[Mobile],[IsActive]);
